{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPb+zUiu0dE4Rya/S6rogAr"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"JK-6WLZnhs4M"},"outputs":[],"source":["# -*- coding: utf-8 -*-\n","import streamlit as st\n","import pandas as pd\n","import numpy as np\n","import matplotlib.pyplot as plt\n","import seaborn as sns\n","import platform\n","import warnings\n","warnings.filterwarnings(\"ignore\")\n","\n","from lifelines import KaplanMeierFitter, CoxPHFitter\n","from sklearn.ensemble import RandomForestClassifier\n","from sklearn.preprocessing import StandardScaler\n","from sklearn.metrics import roc_auc_score, classification_report\n","\n","# =====================================\n","# 0. 기본 환경 설정 (한글 폰트)\n","# =====================================\n","plt.rcParams[\"axes.unicode_minus\"] = False\n","if platform.system() == \"Windows\":\n","    plt.rc(\"font\", family=\"Malgun Gothic\")\n","elif platform.system() == \"Darwin\":\n","    plt.rc(\"font\", family=\"AppleGothic\")\n","else:\n","    plt.rc(\"font\", family=\"NanumGothic\")\n","\n","# =====================================\n","# 1. 제목 및 소개\n","# =====================================\n","st.set_page_config(page_title=\"가맹점 폐업 조기경보 대시보드\", layout=\"wide\")\n","\n","st.title(\"🏪 가맹점 폐업 조기경보 대시보드\")\n","st.markdown(\"\"\"\n","#### 📊 목적:\n","가맹점의 시계열 매출 데이터를 바탕으로 **조기경보 신호**를 예측하고\n","**생존분석 (Cox 모델)** 및 **폐업 위험 순위**를 시각적으로 제공합니다.\n","\"\"\")\n","\n","# =====================================\n","# 2. 데이터 업로드\n","# =====================================\n","st.sidebar.header(\"📂 데이터 불러오기\")\n","\n","uploaded_file = st.sidebar.file_uploader(\"CSV 파일 업로드\", type=[\"csv\"])\n","\n","if uploaded_file is not None:\n","    df = pd.read_csv(uploaded_file)\n","    st.success(f\"✅ 데이터 업로드 완료! (행: {df.shape[0]}, 열: {df.shape[1]})\")\n","else:\n","    st.info(\"왼쪽 사이드바에서 CSV 파일을 업로드하세요.\")\n","    st.stop()\n","\n","# =====================================\n","# 3. 데이터 기본 정보\n","# =====================================\n","st.subheader(\"1️⃣ 데이터 미리보기\")\n","st.dataframe(df.head(10))\n","\n","# 기본 컬럼 자동 인식\n","store_col = \"가맹점구분번호\" if \"가맹점구분번호\" in df.columns else None\n","month_col = \"기준년월\" if \"기준년월\" in df.columns else None\n","\n","if store_col is None or month_col is None:\n","    st.error(\"❌ 필수 컬럼이 없습니다. ('가맹점구분번호', '기준년월')\")\n","    st.stop()\n","\n","# 날짜 변환\n","df[month_col] = pd.to_datetime(df[month_col], errors='coerce')\n","\n","# =====================================\n","# 4. 변수 선택 / 필터링\n","# =====================================\n","st.sidebar.header(\"⚙️ 분석 설정\")\n","\n","numeric_cols = df.select_dtypes(include=np.number).columns.tolist()\n","selected_features = st.sidebar.multiselect(\"사용할 수치형 변수 선택\", numeric_cols)\n","\n","if len(selected_features) == 0:\n","    st.warning(\"분석에 사용할 변수(예: 매출금액, 배달매출 비율 등)를 선택하세요.\")\n","    st.stop()\n","\n","# 기간 필터링\n","if df[month_col].notna().any():\n","    min_date, max_date = df[month_col].min(), df[month_col].max()\n","    selected_period = st.sidebar.slider(\"분석 기간 선택\", min_value=min_date, max_value=max_date, value=(min_date, max_date))\n","    df = df[(df[month_col] >= selected_period[0]) & (df[month_col] <= selected_period[1])]\n","\n","# =====================================\n","# 5. 모델 학습 및 조기경보 예측\n","# =====================================\n","st.subheader(\"2️⃣ 조기경보 모델 학습 및 예측\")\n","\n","target_col = \"조기경보\" if \"조기경보\" in df.columns else None\n","if target_col is None:\n","    st.error(\"❌ 조기경보(Target) 컬럼이 없습니다.\")\n","    st.stop()\n","\n","model_ready = df.dropna(subset=selected_features + [target_col]).copy()\n","X = model_ready[selected_features].values\n","y = model_ready[target_col].values\n","\n","scaler = StandardScaler()\n","X_scaled = scaler.fit_transform(X)\n","\n","rf = RandomForestClassifier(n_estimators=200, max_depth=8, random_state=42)\n","rf.fit(X_scaled, y)\n","y_pred = rf.predict(X_scaled)\n","y_proba = rf.predict_proba(X_scaled)[:, 1]\n","\n","auc = roc_auc_score(y, y_proba)\n","st.metric(label=\"AUC (훈련셋 기준)\", value=f\"{auc:.3f}\")\n","st.text(\"분류 리포트:\")\n","st.text(classification_report(y, y_pred, digits=3))\n","\n","# 변수 중요도 시각화\n","st.subheader(\"📈 변수 중요도 (RandomForest)\")\n","feat_imp = pd.Series(rf.feature_importances_, index=selected_features).sort_values()\n","fig, ax = plt.subplots(figsize=(7, max(3, len(selected_features)*0.4)))\n","feat_imp.plot(kind='barh', ax=ax, color='skyblue')\n","ax.set_xlabel(\"중요도\")\n","st.pyplot(fig)\n","\n","# =====================================\n","# 6. Cox PH 생존분석 (선택)\n","# =====================================\n","st.subheader(\"3️⃣ 생존분석 (Cox Proportional Hazard Model)\")\n","\n","duration_col = st.sidebar.selectbox(\"운영기간(duration) 컬럼 선택\", options=numeric_cols)\n","event_col = st.sidebar.selectbox(\"폐업(event) 컬럼 선택\", options=numeric_cols)\n","\n","if duration_col and event_col:\n","    cox_df = df.dropna(subset=[duration_col, event_col] + selected_features)\n","    if len(cox_df) > 30:\n","        try:\n","            cph = CoxPHFitter()\n","            cph.fit(cox_df[[duration_col, event_col] + selected_features], duration_col=duration_col, event_col=event_col)\n","            st.write(cph.summary)\n","            st.markdown(f\"**C-index:** {cph.concordance_index_:.3f}\")\n","        except Exception as e:\n","            st.error(f\"Cox 모델 적합 중 오류 발생: {e}\")\n","    else:\n","        st.warning(\"Cox 분석을 위한 데이터가 부족합니다.\")\n","\n","# =====================================\n","# 7. Kaplan-Meier 생존곡선 시각화\n","# =====================================\n","st.subheader(\"4️⃣ Kaplan-Meier 생존곡선\")\n","\n","if duration_col and event_col:\n","    from lifelines import KaplanMeierFitter\n","    kmf = KaplanMeierFitter()\n","\n","    fig, ax = plt.subplots(figsize=(7, 5))\n","    kmf.fit(df[duration_col], event_observed=df[event_col], label=\"전체\")\n","    kmf.plot_survival_function(ax=ax)\n","    ax.set_title(\"전체 생존곡선 (Kaplan-Meier)\")\n","    ax.set_xlabel(\"운영기간 (개월)\")\n","    ax.set_ylabel(\"생존확률\")\n","    st.pyplot(fig)\n","\n","# =====================================\n","# 8. 위험 상위 가맹점 리스트\n","# =====================================\n","st.subheader(\"5️⃣ 위험 상위 가맹점 리스트\")\n","\n","df[\"위험확률_RF\"] = np.nan\n","df.loc[model_ready.index, \"위험확률_RF\"] = y_proba\n","top_n = st.slider(\"상위 위험 가맹점 표시 개수\", 5, 50, 20)\n","\n","top_risk = df.sort_values(\"위험확률_RF\", ascending=False).head(top_n)\n","st.dataframe(top_risk[[store_col, month_col, \"위험확률_RF\"] + selected_features])\n","\n","st.download_button(\n","    label=\"📥 위험 가맹점 리스트 다운로드 (CSV)\",\n","    data=top_risk.to_csv(index=False).encode(\"utf-8-sig\"),\n","    file_name=\"top_risk_stores.csv\",\n","    mime=\"text/csv\"\n",")\n","\n","# =====================================\n","# 9. 마무리\n","# =====================================\n","st.success(\"✅ 대시보드 실행 완료!\")\n","st.markdown(\"\"\"\n","---\n","💡 **Tip:**\n","- 변수 선택을 바꾸면 즉시 모델이 다시 학습됩니다.\n","- `Cox PH`는 매장별 생존기간 분석에 적합하며,\n","  `RandomForest`는 조기경보 분류에 활용됩니다.\n","\"\"\")\n"]}]}